import type {Cascade,Win} from './SlotMain';
export const VIKING_MAX_MULTIPLE=5000;
/** Limit a complete symbol-win series, excluding the separate growing bonus.
 * Clip display awards in playback order before adding the final multiplier.
 * Keep matched cells and shared Win objects even when their paid amount is0:
 * otherwise a cap/bonus normalization could stop later falls and effects.
 */
export function vikingCapAwards(stages:readonly Cascade[],bet:number,multiplier:number){
 const maximum=bet*VIKING_MAX_MULTIPLE;
 if(!Number.isSafeInteger(bet)||bet<=0||!Number.isSafeInteger(maximum)||![1,2,3,5,15].includes(multiplier))throw Error('Invalid Viking settlement inputs');
 const seen=new Set<Win>();let rawPayout=0;
 for(const stage of stages)for(const win of stage.wins){
  if(seen.has(win)||!Number.isSafeInteger(win.amount)||win.amount<0)throw Error('Invalid or repeated Viking award');
  seen.add(win);rawPayout+=win.amount;
 }
 const uncappedPayout=rawPayout*multiplier;
 if(!Number.isSafeInteger(uncappedPayout))throw Error('Unsafe Viking settlement total');
 let remaining=maximum;
 for(const stage of stages){
  for(const win of stage.wins){win.amount=Math.min(win.amount,remaining);remaining-=win.amount;}
  stage.payout=stage.wins.reduce((sum,win)=>sum+win.amount,0);
 }
 const basePayout=maximum-remaining,extra=Math.min(rawPayout*(multiplier-1),remaining);
 return {rawPayout,uncappedPayout,basePayout,extra,payout:basePayout+extra,maximum,capReached:uncappedPayout>=maximum};
}
