import {BronzeGuardSlot} from './BronzeGuardSlot';
import {socialSeed} from './Social1921Rules';
export function bronzeGuardAudit(params:URLSearchParams){
 const slot=new BronzeGuardSlot(),outcome=params.get('audit-outcome')||'march';
 slot.demoSpin=bet=>{const rng=socialSeed(418003);for(let i=0;i<200000;i++){const r=slot.spin(bet,rng);if(outcome==='no-win'?!r.rounds&&r.payout===0:outcome==='multi-win'?!r.rounds&&r.wins.length>1:outcome==='retrigger'?r.rounds?.some(q=>q.freeSpinsAdded):r.rounds&&r.rounds.length<=9&&r.rounds.some(q=>q.bronzeFeature?.moves.some(m=>m.to<0)))return r;}throw Error('Bronze audit fixture unavailable');};
 slot.bonusDemoSpin=bet=>{const rng=socialSeed(418011);for(let i=0;i<200000;i++){const r=slot.spin(bet,rng);if(r.freeSpinsAwarded&&r.rounds!.length<=15)return r;}throw Error('Bronze bonus fixture unavailable');};return slot;
}
