import type {SpinResult,Win} from './SlotMain';

export const digitSymbol=(value:number|string)=>'double-lucky-'+value;
export const DIGIT_NUMBERS=Array.from({length:99},(_,i)=>i+1).filter(value=>value%10!==0);
export const DIGIT_DECOR=['bar','double-bar','triple-bar','chip','dice'] as const;
export interface DigitBoost {cell:number;before:number;after:number;}
export interface DigitLink {cells:number[];digits:number[];merged:string;win:Win;}
export interface DigitPlayback {landedBoard:string[];settledBoard:string[];boost?:DigitBoost;links:DigitLink[];ordinaryWins:Win[];}
const integer=(value:number,min=0)=>Number.isSafeInteger(value)&&value>=min;
/** Official tutorial: adjacent numbers concatenate, then pay number / 100 *
 * total bet. The caller selects confirmed winning groups: singleton eligibility,
 * ordinary paytables and jackpot additions remain outside this draft. Whole-coin
 * flooring per link is a local wallet policy, not a verified original rule. */
export function digitResult(landed:(number|string)[],groups:number[][],bet:number,boost?:DigitBoost,ordinary:Win[]=[]):SpinResult{
 if(landed.length!==5||!integer(bet,1)||landed.some(value=>typeof value==='number'?!DIGIT_NUMBERS.includes(value):!DIGIT_DECOR.includes(value as any)))throw Error('Invalid digit board');
 const final=[...landed];
 if(boost){if(!integer(boost.cell)||boost.cell>=5||final[boost.cell]!==boost.before||!DIGIT_NUMBERS.includes(boost.after)||boost.after<=boost.before)throw Error('Invalid digit boost');final[boost.cell]=boost.after;}
 const ordinaryKeys=new Set<string>();
 const ordinaryWins=ordinary.map(win=>{
  if(!integer(win.amount,1)||win.line!==0||win.cells.length<3||new Set(win.cells).size!==win.cells.length||win.cells.some((cell,index)=>!integer(cell)||cell>=5||index>0&&cell!==win.cells[index-1]+1||typeof final[cell]==='number'||digitSymbol(final[cell])!==win.symbol))throw Error('Invalid digit ordinary win');
  // The same settled hit must not be credited twice. Do not deduplicate by
  // line alone: a numeric link can legitimately share this one-line board.
  const key=win.symbol+':'+win.cells.join(',');
  if(ordinaryKeys.has(key))throw Error('Duplicate digit ordinary win');
  ordinaryKeys.add(key);
  return {...win,cells:[...win.cells]};
 });
 const used=new Set<number>(),links:DigitLink[]=[],wins=[...ordinaryWins];
 for(const cells of groups){
  if(!cells.length||cells.some((cell,index)=>!integer(cell)||cell>=5||used.has(cell)||typeof final[cell]!=='number'||index>0&&cell!==cells[index-1]+1))throw Error('Invalid digit link');
  const digits=cells.map(cell=>final[cell] as number),merged=digits.join(''),scaled=Number(merged)*bet;
  if(!integer(scaled))throw Error('Digit payout overflow');
  const amount=Math.floor(scaled/100),win:Win={line:0,symbol:digitSymbol(digits[0]),cells:[...cells],amount};
  cells.forEach(cell=>used.add(cell));links.push({cells:[...cells],digits,merged,win});wins.push(win);
 }
 const payout=wins.reduce((sum,win)=>sum+win.amount,0);if(!integer(payout))throw Error('Digit payout overflow');
 const board=final.map(digitSymbol);
 return {bet,board,wins,payout,digitFeature:{landedBoard:landed.map(digitSymbol),settledBoard:[...board],boost:boost?{...boost}:undefined,links,ordinaryWins}};
}
