export interface NoticeCopy {title:string;body:string;}
export interface LocalizedNotice extends NoticeCopy {localizations?:Record<string,NoticeCopy>;}
export const NOTICE_LANGUAGES=['ko','en','ja','zh-Hans','zh-Hant','de','pt','es','it'] as const;
export function validateNoticeLocalizations(value:unknown):Record<string,NoticeCopy>|undefined {
 if(value===undefined)return undefined;
 if(!value||typeof value!=='object'||Array.isArray(value))throw Error('공지 번역 형식을 확인해 주세요.');
 for(const [locale,text] of Object.entries(value)){
  const t=text as NoticeCopy;
  if(!(NOTICE_LANGUAGES as readonly string[]).includes(locale)||!t||typeof t.title!=='string'||!t.title.trim()||t.title.length>60||typeof t.body!=='string'||t.body.length>3000)throw Error('공지 번역의 언어·제목·내용을 확인해 주세요.');
 }
 return value as Record<string,NoticeCopy>;
}
/** One notice/gift ID carries every translation; language selection never duplicates a claim. */
export function noticeText(notice:LocalizedNotice,locale:string):NoticeCopy {
 return notice.localizations?.[locale]||notice.localizations?.en||{title:notice.title,body:notice.body};
}
