import {audioThemes,slotAudioProfiles,type AudioTheme} from './SlotAudioCatalog';

export const PALETTE_MUSIC_VOLUME=.32;
export const PALETTE_EFFECT_VOLUME=.25;
export const paletteEffectKind=(cue:string)=>cue==='spin'?'spin':cue==='tumbleStart'?'tumble-start':cue==='tumbleHit'?'tumble-hit':cue==='count'?'payout-rise':null;
export const paletteEffect=(slot:string,cue:string)=>{const profile=slotAudioProfiles[slot],kind=paletteEffectKind(cue);return profile&&kind?'slot-audio-v2/'+kind+'-'+profile.theme:null;};

/** Presentation only: never writes save data or changes a round's outcome. */
export class SlotAudioSelection {
 private visits=new Map<string,number>();
 slot='';music:string|null=null;theme:AudioTheme|null=null;
 setScene(scene:string,slot?:string){
  const next=(scene==='slot'||scene==='game-loading')?(slot??''):'';
  if(next===this.slot)return false;
  this.slot=next;this.music=null;this.theme=null;
  const profile=slotAudioProfiles[next];
  if(profile){const visit=this.visits.get(next)??0;this.theme=profile.music[visit%profile.music.length];this.music='slot-audio-v2/music-'+this.theme;this.visits.set(next,visit+1);}
  return true;
 }
 resources(slot:string){
  const profile=slotAudioProfiles[slot];if(!profile)return [];
  const music=this.slot===slot&&this.music?this.music:'slot-audio-v2/music-'+profile.music[0];
  return [music,...['spin','tumbleStart','tumbleHit','count'].map(cue=>paletteEffect(slot,cue)!)];
 }
 get title(){return this.theme?audioThemes[this.theme].name:'';}
 reset(){this.visits.clear();this.slot='';this.music=null;this.theme=null;}
}
