import {SpinResult,Win,CellDrop} from './SlotMain';
import {TumbleGame,TumbleFrame,indices,adjacent,connected,randomIndex,totalWins,tumbleRng} from './TumbleCore';
import {SlotProgress,normalizeSlotProgress,packRounds} from './Social2230Rules';

export class MagnetTapeSlot extends TumbleGame {
 readonly columns=6;readonly rows=6;readonly hasBonus=true;
 readonly config=this.configFor('magnet-tape-studio','자석 테이프 스튜디오','MAGNET TAPE STUDIO',['빨강 테이프','주황 테이프','노랑 테이프','초록 테이프','파랑 테이프','보라 테이프','날개 테이프','음반 상금','자석','증폭기'],['0','1','2','3','4','5','wild','money','magnet','boost'],'6×6 · 연결5개. 자석은 같은 색을 연결 영역으로 이동. 증폭기는 WILD 배수 +2 후 음반으로 변환, 연쇄 당첨마다 +1. WILD3개: 고정 음반 수집3회, 마지막에 연결된 음반만 지급.',[12,12,12,12,12,12,1.4,1,1.2,.7]);
 private magnet(board:string[],frames:TumbleFrame[],rng:()=>number){
  while(board.includes(this.id('magnet'))){const origin=board.indexOf(this.id('magnet'));
   const chosen=this.id(randomIndex(rng,6)),sources=indices(board,chosen);if(!sources.length){board[origin]=this.id('money');continue;}
   // BFS target cells form one connected region, unlike a row-major wrap.
   const targets:number[]=[],queue=[origin],seen=new Set([origin]);
   while(queue.length&&targets.length<sources.length+1){const c=queue.shift()!;if(board[c]!==this.wild&&board[c]!==this.id('boost'))targets.push(c);for(const n of adjacent(c,6,36))if(!seen.has(n)){seen.add(n);queue.push(n);}}
   const tokens=board.map((symbol,from)=>({symbol,from}));tokens[origin].symbol=chosen;
   const matching=tokens.filter(t=>t.symbol===chosen),rest=tokens.filter(t=>t.symbol!==chosen),placed=new Map<number,typeof tokens[number]>();
   targets.slice(0,matching.length).forEach((to,i)=>placed.set(to,matching[i]));const remainder=[...matching.slice(placed.size),...rest];let next=0;
   const moves:CellDrop[]=[];for(let to=0;to<36;to++){const t=placed.get(to)||remainder[next++];board[to]=t.symbol;moves.push({from:t.from,to,symbol:t.symbol});}
   this.frame(frames,board,'move','자석 · 흩어진 테이프를 한곳으로',{moves,cells:targets});
  }
 }
 play(board:string[],bet:number,rng:()=>number):SpinResult{
  this.check(board,bet);board=[...board];const frames:TumbleFrame[]=[];let wildPower=1,trigger=false;
  this.frame(frames,board,'land','테이프 착지');
  for(let step=0;step<40;step++){
   trigger||=indices(board,this.wild!).length>=3;this.magnet(board,frames,rng);
   const boosts=indices(board,this.id('boost'));if(boosts.length){wildPower+=boosts.length*2;boosts.forEach(c=>board[c]=this.id('money'));this.frame(frames,board,'transform','증폭기 → 음반 · WILD ×'+wildPower,{cells:boosts,badges:Object.fromEntries(indices(board,this.wild!).map(c=>[c,'×'+wildPower]))});}
   const wins=this.clusters(board,bet).map(w=>{const m=w.cells.some(c=>board[c]===this.wild)?wildPower:1;w.amount*=m;w.multiplier=m;return w;});
   for(const cells of connected(board,this.id('money'),this.wild,c=>adjacent(c,6,36)))if(cells.length>=5)wins.push(this.prize(bet,cells.length*.1*wildPower,cells,this.id('money')));
   if(!wins.length)break;const remove=new Set(wins.flatMap(w=>w.cells).filter(c=>board[c]!==this.wild));this.frame(frames,board,'win','테이프 클러스터 지급',{wins,cells:Array.from(remove),badges:Object.fromEntries(indices(board,this.wild!).map(c=>[c,'×'+wildPower]))});wildPower++;
   if(!remove.size)break;const next=this.gravity(board,remove,rng,new Set(indices(board,this.wild!)));board=next.board;this.frame(frames,board,'drop','빈자리 테이프 낙하',{moves:next.moves,badges:Object.fromEntries(indices(board,this.wild!).map(c=>[c,'×'+wildPower]))});
   if(step===39)this.frame(frames,board,'state','연쇄40회 안전 종료');
  }
  const base=this.round(bet,frames);if(!trigger)return this.finish([base]);
  const rounds=[base],locked=new Set(indices(board,this.wild!).concat(indices(board,this.id('money'))));
  this.frame(frames,board,'state','차트 진입 · WILD와 음반 고정',{marks:Array.from(locked)});
  for(let left=2;left>=0;left--){const ff:TumbleFrame[]=[];const prior=[...board],held=Array.from(locked);for(let c=0;c<36;c++)if(!locked.has(c)){const r=randomIndex(rng,10);board[c]=r<4?this.id('money'):r===4?this.wild!:this.id('void');}
   this.frame(ff,board,'land','차트 수집 · 남은 '+left+'회',{marks:Array.from(locked),stationary:held});
   for(const c of indices(board,this.id('money')).concat(indices(board,this.wild!)))locked.add(c);
   if(left===0){const wins:Win[]=[];for(const cells of connected(board,this.id('money'),this.wild,c=>adjacent(c,6,36)))if(cells.length>=5)wins.push(this.prize(bet,cells.filter(c=>board[c]===this.id('money')).length*.2*(1+cells.filter(c=>board[c]===this.wild).length),cells,this.id('money')));this.frame(ff,board,'collect','차트 종료 · 연결 음반 한 번 지급',{wins,cells:wins.flatMap(w=>w.cells),marks:Array.from(locked)});}
   const r=this.round(bet,ff);r.heldAtStart=held.map(cell=>({cell,symbol:prior[cell],value:1}));r.freeSpinsRemaining=left;rounds.push(r);
  }return this.finish(rounds,{freeSpinsAwarded:3});
 }
 rawSpin(bet:number,rng:()=>number=Math.random){return this.play(this.draw(rng),bet,rng);}
}

export function gemPattern(pattern:number){return Array.from({length:49},(_,c)=>c).filter(c=>pattern===0?c%7===3||Math.floor(c/7)===3:pattern===1?c%7===Math.floor(c/7)||c%7+Math.floor(c/7)===6:c%7===0||c%7===6||c<7||c>=42);}
export class GemPatternSlot extends TumbleGame {
 readonly columns=7;readonly rows=7;readonly hasBonus=true;private progress:SlotProgress={};
 readonly config=this.configFor('gem-pattern-kingdom','보석 문양 왕국','GEM PATTERN KINGDOM',['홍옥','황옥','에메랄드','청옥','자수정','백수정','왕국 WILD','세계 문'],['0','1','2','3','4','5','wild','portal'],'7×7 · 연결5개. 십자/대각/테두리 문양을 당첨 칸으로 완성. 세 문양마다 광부→왕궁→마법탑 이동·세계 보상. 문양은 베팅별 저장. 한 회전20개 수집 시 세계별 WILD 도움1회. 자체 세계탐험 구매: 세 세계의 충전 회전 각1회, 저장 진행 변경 없음.',[12,12,12,12,12,12,1,0]);
 setProgress(value:SlotProgress){this.progress=normalizeSlotProgress(value);}
 bonusDemoSpin(bet:number){return this.prepareBonusPurchase(bet,tumbleRng(51602026));}
 prepareBonusPurchase(bet:number,rng:()=>number):SpinResult{
  const saved=this.progress,rounds:SpinResult[]=[],captions=['광부의 낙하','왕궁의 다리','마법탑의 모서리'];
  try{
   for(let world=0;world<3;world++){
    this.progress={[this.config.id+':'+bet]:[world,0,0,0,0,0,0,0,0]};
    let selected:SpinResult|undefined;
    for(let attempt=0;attempt<50000;attempt++){const result=this.rawSpin(bet,rng);if(result.tumbleFeature!.frames.some(f=>f.caption===captions[world])){selected=result;break;}}
    if(!selected)throw Error('Natural world charge unavailable');
    delete selected.progressUpdate;selected.roundLabel='세계탐험 '+(world+1)+' / 3';rounds.push(selected);
   }
   let remaining=bet*this.maxWin;
   for(const r of rounds){for(const w of r.wins){w.amount=Math.min(w.amount,remaining);remaining-=w.amount;}r.payout=totalWins(r.wins);}
   return packRounds(rounds,{featureOnly:true,featureName:'세계탐험',presentation:this.presentation,bonusTriggerRound:this.purchaseTrigger(rounds[0])});
  }finally{this.progress=saved;}
 }

 play(board:string[],bet:number,rng:()=>number):SpinResult{
  this.check(board,bet);board=[...board];const saved=this.progress[this.config.id+':'+bet]||Array(9).fill(0),state=[...saved],frames:TumbleFrame[]=[];let count=0,charged=false;
  const uncleared=()=>gemPattern(state[1]).filter(c=>!(state[2+Math.floor(c/7)]&(1<<(c%7))));
  this.frame(frames,board,'land','왕국 '+(state[0]+1)+' · 문양 '+(state[1]+1),{marks:uncleared()});
  for(let step=0;step<40;step++){
   const wins=this.clusters(board,bet),cells=Array.from(new Set(wins.flatMap(w=>w.cells)));
   if(!wins.length){if(count>=20&&!charged){charged=true;const wilds=state[0]===0?[0,6,14,20,28,34]:state[0]===1?[21,22,23,24,25,26,27]:[8,12,36,40];wilds.forEach(c=>board[c]=this.wild!);this.frame(frames,board,'transform',['광부의 낙하','왕궁의 다리','마법탑의 모서리'][state[0]],{cells:wilds,marks:uncleared()});continue;}break;}
   this.frame(frames,board,'win','문양 당첨 · '+cells.length+'칸',{wins,cells,marks:uncleared()});count+=cells.length;
   for(const c of cells)state[2+Math.floor(c/7)]|=1<<(c%7);
   if(!uncleared().length){state[1]++;state.fill(0,2);if(state[1]===3){state[1]=0;state[0]=(state[0]+1)%3;this.frame(frames,board,'collect','다음 세계 개방',{wins:[this.prize(bet,2,cells,this.id('portal'))],cells});}this.frame(frames,board,'state','새 문양 '+(state[1]+1),{marks:uncleared()});}
   const next=this.gravity(board,new Set(cells),rng);board=next.board;this.frame(frames,board,'drop','수정 낙하',{moves:next.moves,marks:uncleared()});if(step===39)this.frame(frames,board,'state','연쇄40회 안전 종료');
  }
  return this.finish([this.round(bet,frames)],{progressUpdate:{key:this.config.id+':'+bet,values:state}});
 }
 rawSpin(bet:number,rng:()=>number=Math.random){return this.play(this.draw(rng),bet,rng);}
}

export class SignalStackSlot extends TumbleGame {
 readonly columns=5;readonly rows=7;readonly hasBonus=true;
 readonly config=this.configFor('signal-stack-ruins','신호를 쌓는 유적','SIGNAL STACK RUINS',['태양 석판','달 석판','파도 석판','잎 석판','불 석판','눈 석판'],['0','1','2','3','4','5'],'5×7 · 연결5개. 당첨 심볼을 남기고 비당첨만 제거. 계속 커진 당첨 집합은 회전 종료 때 한 번 지급. 위쪽 행 도달: 무료3회, 전판 완성:6회. 무료에서는 집합 유지·행 완성 배수, 마지막 회전에만 전체 집합 지급.');
 private grow(initial:string[],bet:number,rng:()=>number,retained=new Set<number>(),free=false){
  let board=[...initial],locked=new Set(retained),frames:TumbleFrame[]=[],passes=0;
  this.frame(frames,board,'land',free?'유적 무료 · 수집 집합 유지':'신호 탐색',{marks:Array.from(locked),stationary:Array.from(retained)});
  for(;passes<35;passes++){
   const wins=this.clusters(board,bet),matching=new Set(wins.flatMap(w=>w.cells)),fresh=Array.from(matching).filter(c=>!locked.has(c));if(!fresh.length)break;
   fresh.forEach(c=>locked.add(c));this.frame(frames,board,'state','당첨 집합 확대 · 아직 미정산',{cells:fresh,marks:Array.from(locked)});
   if(locked.size===35)break;
   const remove=new Set(board.map((_,c)=>c).filter(c=>!locked.has(c))),next=this.gravity(board,remove,rng);
   locked=new Set(next.moves.filter(m=>m.from>=0&&locked.has(m.from)).map(m=>m.to));board=next.board;
   this.frame(frames,board,'drop','비당첨만 제거 · 당첨 집합은 내려와 유지',{moves:next.moves,marks:Array.from(locked),cells:Array.from(remove)});
  }
  const fullRows=[0,1,2,3,4,5,6].filter(r=>Array.from({length:5},(_,c)=>r*5+c).every(c=>locked.has(c))),multiplier=1+fullRows.length;
  const wins=this.clusters(board,bet,multiplier).filter(w=>w.cells.some(c=>locked.has(c)));
  this.frame(frames,board,'collect','집합 최종 정산 ×'+multiplier,{wins,cells:wins.flatMap(w=>w.cells),marks:Array.from(locked)});
  return{round:this.round(bet,frames,passes>=35?'safety-cap':'settled'),locked,board,trigger:Array.from(locked).some(c=>c<5)};
 }
 play(board:string[],bet:number,rng:()=>number):SpinResult{
  this.check(board,bet);const base=this.grow(board,bet,rng);if(!base.trigger)return this.finish([base.round]);const initial=base.locked.size===35?6:3,rounds=[base.round];let last=base;
  for(let left=initial-1;left>=0;left--){const b=this.draw(rng);last.locked.forEach(c=>b[c]=last.board[c]);const next=this.grow(b,bet,rng,last.locked,true);if(left>0&&next.locked.size<35){for(const f of next.round.tumbleFeature!.frames){f.wins=[];if(f.action==='collect')f.caption='신호 집합 보관 · 무료 종료 때 지급';}next.round.wins=[];next.round.payout=0;}next.round.freeSpinsRemaining=left;rounds.push(next.round);last=next;
   if(last.locked.size===35){const f=last.round.tumbleFeature!.frames;this.frame(f,last.board,'collect','전판 완성 · 남은 회전 정산',{wins:left?[this.prize(bet,left*2,Array.from(last.locked))]:[]});last.round.wins=f.flatMap(x=>x.wins);last.round.payout=totalWins(last.round.wins);last.round.freeSpinsRemaining=0;break;}
  }return this.finish(rounds,{freeSpinsAwarded:initial});
 }
 rawSpin(bet:number,rng:()=>number=Math.random){return this.play(this.draw(rng),bet,rng);}
}
