import {SlotMain,SlotConfig,SpinResult} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {SERIAL_ART,SERIAL_EFFECT_ART,serialSymbol as s,serialVisible,serialSequence,SerialTurn} from './SerialFeature';
export class SerialPreviewSlot extends SlotMain {
 constructor(private readonly fixture='hold'){super();}
 readonly columns=5;readonly rows=5;readonly mode='lines' as const;readonly paylines:number[][]=[];readonly bets=[...BET_LEVELS];
 readonly config:SlotConfig={id:'serial-kitchen',title:'시리얼 키친',subtitle:'SERIAL KITCHEN',tag:'전용 고정 체험',color:'#392f45',accent:'#d4b4cf',description:'당첨 심볼 고정 · 나머지 리스핀\n당첨 개선 시 좌측부터 상하 확장\n복제 장치 · 같은 심볼 2–4개\n전염형은 같은 심볼에 전파\n마지막 릴 WILD · 같은 행 분할',symbols:SERIAL_ART.map(art=>({id:s(art),name:art.endsWith('_wild')?'WILD':art.replace(/_/g,' '),color:'#d4b4cf',weight:0,payout:0}))};
 artResource(id:string){const name=id.slice('serial-kitchen-'.length);if(![...SERIAL_ART,...SERIAL_EFFECT_ART].includes(name))throw Error('Unknown Serial art');return 'slot-art-delivered-v1/serial-kitchen/v05/'+name;}
 spin():SpinResult{throw Error('Serial first draft is free playback only');}
 demoSpin(bet:number):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  const blank=(opened=0)=>Array.from({length:25},(_,cell)=>serialVisible(cell,opened)?s(SERIAL_ART[(cell+cell%5)%10]):s('void'));
  const initial=blank();if(this.fixture==='no-win')return serialSequence(initial,[{board:blank(),effects:[],wins:[]}],bet);
  const a=blank();[10,11,12].forEach(cell=>a[cell]=s('doctor'));
  const b=blank(1);[10,11,12].forEach(cell=>b[cell]=s('doctor'));b[8]=s('ways_device');b[14]=s('split_wild');
  const turns:SerialTurn[]=[{board:a,effects:[],wins:[{line:-1,symbol:s('doctor'),amount:bet,cells:[10,11,12]}],extension:[s('masked_figure'),s('nudge_wild')]},{board:b,effects:[{kind:'ways',cell:8,symbol:s('doctor'),count:2,infectious:true},{kind:'split',cell:14}],wins:[{line:-1,symbol:s('doctor'),amount:bet*3,cells:[10,11,12,14]}],extension:[s('investigator'),s('plain_wild')]}];
  const c=blank(2);[10,11,12].forEach(cell=>c[cell]=s('doctor'));c[14]=s('split_wild');
  turns.push({board:c,effects:[],wins:[{line:-1,symbol:s('doctor'),amount:bet*3,cells:[10,11,12,14]}]});return serialSequence(initial,turns,bet);
 }
}
