import {SpinResult,Win} from './SlotMain';
import {Social2230LineSlot,socialPresentation,sumResult} from './Social2230Rules';
import {socialSeed} from './Social1921Rules';
export interface CannonPlayback {shots:{cell:number;win:Win}[];}
export class GemCannonSlot extends Social2230LineSlot {
 readonly presentation=socialPresentation('대포 발사 → 표적 공개 → 지급','보석 대포 공개');
 readonly config=this.namedConfig('gem-cannon-theatre','보석 대포 극장','GEM CANNON THEATRE',['극장 가면','다이아 표적','대포 바퀴','붉은 커튼','발사 심지','공연 깃털','탄약 상자','무대 종','조준경 WILD','대포 초대장'],'초대장 3개 이상: 서로 다른 표적 3곳을 순서대로 공개합니다.\n표적당 베팅 ×1/2/5/10. 일반 라인과 별도로 한 번씩 지급.\n공개 중 재진입 없음.','#3c304d','#bfa9f2');
 spin(bet:number,rng:()=>number=Math.random):SpinResult{
  const r=this.draw(bet,rng),shots:CannonPlayback['shots']=[];
  if(r.board.filter(s=>s===this.config.id+'-scatter').length>=3){const cells=Array.from({length:15},(_,c)=>c);for(let i=0;i<3;i++){const cell=cells.splice(Math.min(cells.length-1,Math.floor(rng()*cells.length)),1)[0],v=rng(),multiplier=v<.7?1:v<.9?2:v<.98?5:10,win:Win={line:-1,symbol:this.config.id+'-scatter',cells:[cell],multiplier,amount:bet*multiplier};r.wins.push(win);shots.push({cell,win});}}
  r.cannonFeature={shots};return sumResult(r);
 }
 demoSpin(bet:number){const rng=socialSeed(23);for(let i=0;i<20000;i++){const r=this.spin(bet,rng);if(r.cannonFeature!.shots.length)return r;}throw Error('Cannon preview unavailable');}
}
