const DAY_MS=86_400_000;
const KST_OFFSET_MS=9*60*60*1000;

export const WEEKLY_FREE_SPIN_BET=50;
export const WEEKLY_FREE_SPIN_COUNT=50;
export const WEEKLY_FREE_SPIN_REWARD=6000;
export const WEEKLY_FREE_SPIN_DAYS=['월','화','수','목','금','토'] as const;

export type WeeklyFreeSpinStatus='idle'|'active'|'completed'|'forfeited';
export interface WeeklyFreeSpinPlan {weekKey:string;slots:string[];}
export interface WeeklyFreeSpinDayState {status:WeeklyFreeSpinStatus;played:number;}
export interface WeeklyFreeSpinState {weekKey:string;days:WeeklyFreeSpinDayState[];rewardGranted:boolean;}
export interface WeeklyFreeSpinToday {
 day:number;
 dayName:typeof WEEKLY_FREE_SPIN_DAYS[number];
 slotId:string;
 status:WeeklyFreeSpinStatus;
 played:number;
 remaining:number;
}

const emptyDay=():WeeklyFreeSpinDayState=>({status:'idle',played:0});
export const newWeeklyFreeSpins=():WeeklyFreeSpinState=>({weekKey:'',days:Array.from({length:6},emptyDay),rewardGranted:false});

function dateOrdinal(key:string){return Date.parse(key+'T00:00:00Z')/DAY_MS;}
function kstOrdinal(now:number){return Math.floor((now+KST_OFFSET_MS)/DAY_MS);}

export function validateWeeklyFreeSpinPlan(value:unknown):WeeklyFreeSpinPlan {
 const v=value as WeeklyFreeSpinPlan;
 if(!v||typeof v!=='object'||typeof v.weekKey!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(v.weekKey)||!Array.isArray(v.slots)||v.slots.length!==6||v.slots.some(id=>typeof id!=='string'||!/^[a-z0-9-]{1,80}$/.test(id)))throw Error('주간 프리스핀 설정 형식 오류');
 const start=dateOrdinal(v.weekKey);
 if(!Number.isInteger(start)||new Date(v.weekKey+'T00:00:00Z').toISOString().slice(0,10)!==v.weekKey||new Date(v.weekKey+'T00:00:00Z').getUTCDay()!==1)throw Error('주간 프리스핀 시작일은 월요일이어야 합니다.');
 return {weekKey:v.weekKey,slots:[...v.slots]};
}

export function normalizeWeeklyFreeSpins(value:unknown):WeeklyFreeSpinState {
 const v=value as Partial<WeeklyFreeSpinState>|null;
 if(!v||typeof v!=='object'||typeof v.weekKey!=='string'||!Array.isArray(v.days)||v.days.length!==6)return newWeeklyFreeSpins();
 const days=v.days.map((day:any)=>{
  const played=Number.isSafeInteger(day?.played)?Math.max(0,Math.min(WEEKLY_FREE_SPIN_COUNT,day.played)):0;
  const status:WeeklyFreeSpinStatus=['idle','active','completed','forfeited'].includes(day?.status)?day.status:'idle';
  if(status==='completed'||played>=WEEKLY_FREE_SPIN_COUNT)return {status:'completed' as const,played:WEEKLY_FREE_SPIN_COUNT};
  if(status==='forfeited')return {status:'forfeited' as const,played};
  return {status:status==='active'?'active' as const:'idle' as const,played};
 });
 return {weekKey:v.weekKey,days,rewardGranted:v.rewardGranted===true};
}

export function weeklyFreeSpinDayIndex(plan:WeeklyFreeSpinPlan,now=Date.now()){
 const checked=validateWeeklyFreeSpinPlan(plan),day=kstOrdinal(now)-dateOrdinal(checked.weekKey);
 return Number.isInteger(day)&&day>=0&&day<6?day:-1;
}

/** Applies calendar rollover in Korea time. Missed or abandoned days cannot be reopened. */
export function syncWeeklyFreeSpins(value:WeeklyFreeSpinState,plan:WeeklyFreeSpinPlan,now=Date.now()){
 const checked=validateWeeklyFreeSpinPlan(plan);
 let state=normalizeWeeklyFreeSpins(value);
 if(state.weekKey!==checked.weekKey)state={weekKey:checked.weekKey,days:Array.from({length:6},emptyDay),rewardGranted:false};
 const current=kstOrdinal(now)-dateOrdinal(checked.weekKey),days=state.days.map(day=>({...day}));
 const passed=Math.max(0,Math.min(6,current));
 for(let i=0;i<passed;i++)if(days[i].status==='idle'||days[i].status==='active')days[i]={...days[i],status:'forfeited'};
 if(current>=0&&current<6)for(let i=0;i<6;i++)if(i!==current&&days[i].status==='active')days[i]={...days[i],status:'forfeited'};
 return {...state,days};
}

export function weeklyFreeSpinToday(value:WeeklyFreeSpinState,plan:WeeklyFreeSpinPlan,now=Date.now()):WeeklyFreeSpinToday|null {
 const checked=validateWeeklyFreeSpinPlan(plan),state=syncWeeklyFreeSpins(value,checked,now),day=weeklyFreeSpinDayIndex(checked,now);
 if(day<0)return null;
 const item=state.days[day];
 return {day,dayName:WEEKLY_FREE_SPIN_DAYS[day],slotId:checked.slots[day],status:item.status,played:item.played,remaining:Math.max(0,WEEKLY_FREE_SPIN_COUNT-item.played)};
}

export function startWeeklyFreeSpins(value:WeeklyFreeSpinState,plan:WeeklyFreeSpinPlan,now=Date.now()){
 const checked=validateWeeklyFreeSpinPlan(plan),state=syncWeeklyFreeSpins(value,checked,now),day=weeklyFreeSpinDayIndex(checked,now);
 if(day<0)throw Error('오늘 진행할 주간 프리스핀이 없습니다.');
 const current=state.days[day];
 if(current.status==='completed')throw Error('오늘 프리스핀은 이미 완료했습니다.');
 if(current.status==='forfeited')throw Error('오늘 프리스핀은 이미 종료되었습니다.');
 if(current.status==='active')return state;
 const days=state.days.map(item=>({...item}));days[day]={status:'active',played:current.played};
 return {...state,days};
}

export function forfeitWeeklyFreeSpins(value:WeeklyFreeSpinState,plan:WeeklyFreeSpinPlan,now=Date.now()){
 const checked=validateWeeklyFreeSpinPlan(plan),state=syncWeeklyFreeSpins(value,checked,now),day=weeklyFreeSpinDayIndex(checked,now);
 if(day<0)return state;
 const current=state.days[day];if(current.status!=='active')return state;
 const days=state.days.map(item=>({...item}));days[day]={...current,status:'forfeited'};
 return {...state,days};
}

export function recordWeeklyFreeSpin(value:WeeklyFreeSpinState,plan:WeeklyFreeSpinPlan,slotId:string,now=Date.now()){
 const checked=validateWeeklyFreeSpinPlan(plan),state=syncWeeklyFreeSpins(value,checked,now),day=weeklyFreeSpinDayIndex(checked,now);
 if(day<0||checked.slots[day]!==slotId)throw Error('오늘 지정된 프리스핀 슬롯이 아닙니다.');
 const current=state.days[day];if(current.status!=='active'||current.played>=WEEKLY_FREE_SPIN_COUNT)throw Error('주간 프리스핀 세션이 활성화되지 않았습니다.');
 const played=current.played+1,days=state.days.map(item=>({...item}));days[day]={status:played>=WEEKLY_FREE_SPIN_COUNT?'completed':'active',played};
 let rewardGranted=state.rewardGranted,rewardCoins=0;
 if(!rewardGranted&&days.every(item=>item.status==='completed')){rewardGranted=true;rewardCoins=WEEKLY_FREE_SPIN_REWARD;}
 return {state:{...state,days,rewardGranted},rewardCoins,day,played,completed:played>=WEEKLY_FREE_SPIN_COUNT};
}
