// Keep authored feature pauses short; never stretch a reading beat into seconds.
export const SLOT_PAUSE_SCALE=.3;
export const AUTO_SPIN_GAP=.08;
export const BONUS_ENTRY_SECONDS=.3;
export const BONUS_EXIT_SECONDS=.4;
// reelStop adds its 210ms settling bounce after this scrolling phase.
export const reelSpinSeconds=(column:number)=>Math.min(.78,.4+Math.max(0,column)*.075);
export const detailHold=(caption:string,_style:FeatureStyle)=>Math.min(.5,Math.max(.3,.2+Array.from(caption).length*.006));
export const validDetailCells=(cells:number[],size:number)=>Array.from(new Set(cells)).filter(c=>Number.isInteger(c)&&c>=0&&c<size);
export function orbitPoint(from:{x:number;y:number},to:{x:number;y:number},center:{x:number;y:number},progress:number){
 if(progress<=0)return {...from};if(progress>=1)return {...to};
 const ax=from.x-center.x,ay=from.y-center.y,bx=to.x-center.x,by=to.y-center.y,a=Math.atan2(ay,ax),b=Math.atan2(by,bx);
 let delta=b-a;while(delta>Math.PI)delta-=Math.PI*2;while(delta< -Math.PI)delta+=Math.PI*2;
 const radius=Math.hypot(ax,ay)+(Math.hypot(bx,by)-Math.hypot(ax,ay))*progress;
 return{x:center.x+Math.cos(a+delta*progress)*radius,y:center.y+Math.sin(a+delta*progress)*radius};
}
/** Authored causes for otherwise terse engine captions; amounts stay in the result. */
export function tumbleReason(id:string,caption:string){
 if(id==='gem-pattern-kingdom'){
  if(['광부의 낙하','왕궁의 다리','마법탑의 모서리'].includes(caption))return '당첨 20칸 누적 → '+caption;
  if(caption.startsWith('새 문양'))return '현재 문양 완성 → '+caption;
  if(caption==='다음 세계 개방')return '문양 3개 완성 → 다음 세계';
 }
 if(id==='golden-reaction-lab'&&['전판 반응','WILD 반응','사각 반응','거대 반응','마지막 WILD 반응'].includes(caption))return '표식 칸 당첨 → '+caption;
 if(id==='prism-split-forge'&&caption.includes('릴 분할'))return '보조색 당첨 → '+caption;
 if(id==='buried-gate-chambers'&&caption.startsWith('봉인 돌'))return '인접 칸 당첨 → '+caption;
 if(id==='parrot-frontier'&&caption==='열매 등급 상승')return '깃털 수집 → 열매 등급 상승';
 if(caption==='세 링 회전')return '클러스터 당첨 → 세 링 회전';
 if(caption==='판 전체 반시계90도 회전')return '당첨 칸 확정 → 판 전체 90도 회전';
 return caption;
}
