import type {SpinResult,Win} from './SlotMain';
export const QUICK_SYMBOLS=['cherry','bell','seven','double-seven','bar','wild','bonus','quick-chip'] as const;
export const quickSymbol=(name:string)=>'huuuge-jackpot-club-'+name;
export interface QuickPackage {spins:number;multiplier:number;}
export interface QuickPick {cell:number;value:QuickPackage;matches:number;complete:boolean;}
export interface QuickTurn {board:string[];wins:Win[];}
export interface QuickPlayback {triggerBoard:string[];triggerCells:number[];triggerWins:Win[];picks:QuickPick[];selected:QuickPackage;stages:{board:string[];baseWins:Win[];wins:Win[];remainingBefore:number;remainingAfter:number}[];}
export const QUICK_CHIP_COUNTS=[5,6,7,8,9] as const;
export type QuickChipCount=typeof QUICK_CHIP_COUNTS[number];
/** Absolute coin amounts supplied by the caller, not bet multipliers or
 * recovered provider jackpot values. The formula never invents a tier. */
export interface QuickChipRules {
 awardsByCount:Record<QuickChipCount,number>;
 phase:'base'|'trigger'|'free';
 packageMultiplierPolicy:{kind:'excluded'}|{kind:'apply';multiplier:number};
}
export interface QuickChipPlayback {
 ruleSource:'caller-supplied';phase:QuickChipRules['phase'];
 packageMultiplierPolicy:QuickChipRules['packageMultiplierPolicy'];
 chipCells:number[];chipCount:number;tier?:QuickChipCount;baseChipAmount:number;
 ordinaryWins:Win[];chipAward?:Win;totalBefore:number;totalAfter:number;
}
function boardOK(board:string[]){if(board.length!==15||board.some(id=>!QUICK_SYMBOLS.some(name=>quickSymbol(name)===id)))throw Error('Invalid quick board');}
function copyWins(input:Win[]){return input.map(win=>{
 if(!Number.isSafeInteger(win.amount)||win.amount<1||!win.cells.length||new Set(win.cells).size!==win.cells.length||win.cells.some(cell=>!Number.isInteger(cell)||cell<0||cell>=15))throw Error('Invalid quick win');
 return {...win,cells:[...win.cells]};
});}
/** The recorded promo shows separate 5/6/7/8/9-chip rows only. Amounts,
 * package-multiplier interaction, resets and probabilities remain unverified.
 * Ordinary wins are already-settled amounts and are never multiplied here.
 * Do not pass this result's combined wins through quickFreeSequence: that
 * function scales line wins, while this contract settles its own chip policy. */
export function quickChipRound(board:string[],bet:number,ordinaryInput:Win[],rules:QuickChipRules):SpinResult&{quickChipFeature:QuickChipPlayback}{
 boardOK(board);
 if(!Number.isSafeInteger(bet)||bet<1)throw Error('Invalid quick chip bet');
 const chipCells=board.flatMap((symbol,cell)=>symbol===quickSymbol('quick-chip')?[cell]:[]),chipCount=chipCells.length;
 if(chipCount>9)throw Error('Quick chip counts above 9 are unconfirmed and unsupported');
 if(!rules||!['base','trigger','free'].includes(rules.phase)||!rules.awardsByCount||Object.keys(rules.awardsByCount).length!==5||Object.keys(rules.awardsByCount).some(key=>!QUICK_CHIP_COUNTS.some(count=>String(count)===key))||QUICK_CHIP_COUNTS.some(count=>!Number.isSafeInteger(rules.awardsByCount[count])||rules.awardsByCount[count]<1))throw Error('Explicit quick chip 5-9 payout table and phase required');
 const policy=rules.packageMultiplierPolicy;
 if(!policy||(policy.kind!=='excluded'&&policy.kind!=='apply')||(policy.kind==='apply'&&(!Number.isSafeInteger(policy.multiplier)||policy.multiplier<1)))throw Error('Explicit quick chip package multiplier policy required');
 const ordinaryWins=copyWins(ordinaryInput),ordinaryKeys=new Set<string>();
 for(const win of ordinaryWins){
  if(win.symbol===quickSymbol('quick-chip'))throw Error('Quick chip award must not be supplied as an ordinary win');
  const key=win.line+':'+win.symbol+':'+win.cells.join(',');
  if(ordinaryKeys.has(key))throw Error('Duplicate quick ordinary win');ordinaryKeys.add(key);
 }
 const totalBefore=ordinaryWins.reduce((sum,win)=>sum+win.amount,0);
 if(!Number.isSafeInteger(totalBefore))throw Error('Quick chip payout overflow');
 const tier=QUICK_CHIP_COUNTS.find(count=>count===chipCount),baseChipAmount=tier===undefined?0:rules.awardsByCount[tier];
 const amount=baseChipAmount*(policy.kind==='apply'?policy.multiplier:1);
 if(!Number.isSafeInteger(amount)||!Number.isSafeInteger(totalBefore+amount))throw Error('Quick chip payout overflow');
 const chipAward:Win|undefined=tier===undefined?undefined:{line:-1,symbol:quickSymbol('quick-chip'),cells:[...chipCells],amount,...(policy.kind==='apply'?{multiplier:policy.multiplier}:{})};
 const wins=chipAward?[...ordinaryWins,chipAward]:[...ordinaryWins];
 const quickChipFeature:QuickChipPlayback={ruleSource:'caller-supplied',phase:rules.phase,packageMultiplierPolicy:{...policy},chipCells:[...chipCells],chipCount,tier,baseChipAmount,ordinaryWins,chipAward,totalBefore,totalAfter:totalBefore+amount};
 return {bet,board:[...board],wins,payout:quickChipFeature.totalAfter,quickChipFeature};
}
/** Official promo: pick covered clovers until three matching free-spin and
 * multiplier packages. Hidden values stay out of the presentation results. */
export function quickPickSequence(deck:QuickPackage[],order:number[]):{picks:QuickPick[];selected:QuickPackage}{
 if(deck.length!==20||deck.some(value=>!Number.isSafeInteger(value.spins)||value.spins<1||value.spins>100||!Number.isSafeInteger(value.multiplier)||value.multiplier<1||value.multiplier>100))throw Error('Invalid quick deck');
 const counts=new Map<string,number>(),used=new Set<number>(),picks:QuickPick[]=[];let selected:QuickPackage|undefined;
 for(const cell of order){
  if(selected||!Number.isInteger(cell)||cell<0||cell>=20||used.has(cell))throw Error('Invalid quick pick order');used.add(cell);
  const value={...deck[cell]},key=value.spins+':'+value.multiplier,matches=(counts.get(key)||0)+1;counts.set(key,matches);const complete=matches===3;picks.push({cell,value,matches,complete});if(complete)selected={...value};
 }
 if(!selected)throw Error('Quick pick did not match three');return {picks,selected};
}
export function quickFreeSequence(triggerBoard:string[],deck:QuickPackage[],order:number[],turns:QuickTurn[],bet:number,triggerInput:Win[]=[]):SpinResult{
 boardOK(triggerBoard);const triggerCells=triggerBoard.flatMap((id,cell)=>id===quickSymbol('bonus')?[cell]:[]),pick=quickPickSequence(deck,order);
 if(triggerCells.length<3||turns.length!==pick.selected.spins||!Number.isSafeInteger(bet)||bet<1)throw Error('Invalid quick free sequence');
 // The package multiplier belongs to awarded free spins. Preserve a supplied
 // trigger-spin line win as-is and settle it before showing the pick board.
 const triggerWins=copyWins(triggerInput),wins:Win[]=[...triggerWins],stages:QuickPlayback['stages']=[];
 for(const [index,turn]of turns.entries()){
  boardOK(turn.board);const baseWins=copyWins(turn.wins);
  const paid=baseWins.map(win=>{const amount=win.amount*pick.selected.multiplier;if(!Number.isSafeInteger(amount))throw Error('Quick payout overflow');return {...win,cells:[...win.cells],amount,multiplier:pick.selected.multiplier};});wins.push(...paid);stages.push({board:[...turn.board],baseWins,wins:paid,remainingBefore:turns.length-index,remainingAfter:turns.length-index-1});
 }
 const payout=wins.reduce((sum,win)=>sum+win.amount,0);if(!Number.isSafeInteger(payout))throw Error('Quick payout overflow');
 return {bet,board:[...turns[turns.length-1].board],payout,wins,quickFeature:{triggerBoard:[...triggerBoard],triggerCells,triggerWins,...pick,stages}};
}
