import {CrystalSealSlot} from './CrystalSealSlot';
export function crystalSealAudit(params:URLSearchParams){const slot=new CrystalSealSlot(),outcome=params.get('audit-outcome');
 if(['clear','no-win','single-win','multi-win'].includes(outcome||''))slot.demoSpin=bet=>{let seed=359281;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};slot.setProgress({});for(let i=0;i<100000;i++){const r=slot.spin(bet,rng);if(outcome==='clear'?!!r.rounds:!r.rounds&&(outcome==='no-win'?r.wins.length===0:outcome==='single-win'?r.wins.length>0&&new Set(r.wins.map(w=>w.symbol)).size===1:new Set(r.wins.map(w=>w.symbol)).size>1))return r;slot.setProgress({[r.progressUpdate!.key]:r.progressUpdate!.values});}throw Error('Seal natural sequence unavailable');};return slot;}
