import {isLocalMode} from './LocalMode';
import {getApps,getAuth,getFirestore,doc,runTransaction,serverTimestamp} from '../vendor/firebase-sdk.js';
import {CrashReport} from './CrashReports';
export async function sendCrashReport(report:CrashReport){
 if(isLocalMode())return;
 const app=getApps().find(a=>a.name==='in-my-pocket'),user=app&&getAuth(app).currentUser;
 if(!app||!user)throw Error('Diagnostics wait for sign-in');
 const db=getFirestore(app),ref=doc(db,'clientErrors',user.uid+'-'+report.id);
 // Stable IDs deduplicate retries after lost acknowledgements.
 await runTransaction(db,async tx=>{const old=await tx.get(ref);if(!old.exists())tx.set(ref,{uid:user.uid,createdAt:serverTimestamp(),report});});
}
